// The parts catalogue (engine/parts/catalog.json, generated by tools/bake.mjs) and the geometry of a placed part in the model frame.
import fs from 'node:fs'; import path from 'node:path'; import { fileURLToPath } from 'node:url';
const DIR = path.dirname(fileURLToPath(import.meta.url));
export const CATALOG = JSON.parse(fs.readFileSync(path.join(DIR, 'parts/catalog.json'), 'utf8'));
const ALIAS = {};   // retired ids the LDraw library renamed (3023 → 3023b): accept the common number
for (const id of Object.keys(CATALOG)) { const m = /^(\d+)[a-c]$/.exec(id); if (m && !CATALOG[m[1]]) ALIAS[m[1]] = id; }
export function part(id) { id = String(id).toLowerCase().replace(/\.dat$/, ''); return CATALOG[id] ?? CATALOG[ALIAS[id]] ?? null; }
export const footprint = (def, rot) => (!def ? [1, 1] : rot % 2 === 0 ? [def.w, def.d] : [def.d, def.w]);
export const PL = 0.4;   // a plate, in studs
/** rotate an offset (x, z) about the vertical axis by rot quarter turns (counter-clockwise seen from above: +x → −z) */
export const turn = (x, z, rot) => [[x, z], [z, -x], [-x, -z], [-z, x]][rot & 3];
/** row-major 3×3 rotation for rot quarter turns, matching `turn` */
export const rotM = (rot) => { const [c, s] = [[1, 0], [0, 1], [-1, 0], [0, -1]][rot & 3]; return [c, 0, s, 0, 1, 0, -s, 0, c]; };
const mulv = (m, v) => [m[0] * v[0] + m[1] * v[1] + m[2] * v[2], m[3] * v[0] + m[4] * v[1] + m[5] * v[2], m[6] * v[0] + m[7] * v[1] + m[8] * v[2]];

/** Everything the checker and the viewer need about one placement, in model units (x, z studs; y studs too, i.e. plates × 0.4).
 *  `pins` are the mating points in world space: `stud` = a peg pointing out along `ax`, `socket` = a hole whose mouth faces out
 *  along `ax`. A stud seats in a socket when the two sit at the same point and face each other. Side studs are just stud pins with
 *  a horizontal axis, which is what lets SNOT hang off a 4733 or a bracket and still be checked. */
export function resolve(p) {
  const def = part(p.id);
  const { m, origin } = frame(p, def);
  const b = def.body; const base = def.base ?? b[1];
  const world = (x, yPl, z) => { const w = mulv(m, [x, base + yPl * PL, z]); return [w[0] + origin[0], w[1] + origin[1], w[2] + origin[2]]; };
  const dir = (v) => mulv(m, v);
  const pins = { stud: [], socket: [] };
  for (const [x, z, y] of def.studs) pins.stud.push({ p: world(x, y, z), ax: dir([0, 1, 0]) });
  for (const [x, z, y, dx, dz] of def.side ?? []) pins.stud.push({ p: world(x, y, z), ax: dir([dx, 0, dz]) });
  for (const [x, z] of def.female) pins.socket.push({ p: world(x, 0, z), ax: dir([0, -1, 0]) });
  if (p.free) {   // exact transform: corners of the body box → world AABB
    let lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
    for (const x of [b[0], b[3]]) for (const y of [b[1], b[4]]) for (const z of [b[2], b[5]]) { const w = mulv(m, [x, y, z]); for (let i = 0; i < 3; i++) { lo[i] = Math.min(lo[i], w[i] + origin[i]); hi[i] = Math.max(hi[i], w[i] + origin[i]); } }
    return { def, origin, m, aabb: [...lo, ...hi], studs: [], female: [], cols: [], pins, free: true };
  }
  const [fw, fd] = footprint(def, p.rot); const y0 = p.y;
  const at = (x, z) => { const [a, c] = turn(x, z, p.rot); return [p.x + fw / 2 + a, p.z + fd / 2 + c]; };
  return {
    def, origin, m, fw, fd,
    aabb: [p.x, y0 * PL, p.z, p.x + fw, (y0 + def.h) * PL, p.z + fd],
    studs: def.studs.map(([x, z, y]) => [...at(x, z), y0 + y]),
    female: def.female.map(([x, z]) => at(x, z)),
    cols: def.cols.map(([x, z, a, c]) => [...at(x, z), y0 + a, y0 + c]),
    pins,
  };
}

/** the placement's rotation and the world point its part-local origin (the middle of its base) lands on */
function frame(p, def) {
  if (p.free) return { m: p.free.m, origin: p.free.p };
  const [fw, fd] = footprint(def, p.rot); const m = rotM(p.rot); const b = def.body;
  const bc = [(b[0] + b[3]) / 2, def.base ?? b[1], (b[2] + b[5]) / 2];
  const r = mulv(m, bc);
  return { m, origin: [p.x + fw / 2 - r[0], p.y * PL - r[1], p.z + fd / 2 - r[2]] };
}
